import sys
from collections import Counter

data = sys.stdin.read().split()
n = int(data[0])
carry = Counter()
moves = 0
for i in range(n):
    for ch in data[1 + 2 * i]:
        carry[ch] += 1
    for ch in data[2 + 2 * i]:
        carry[ch] -= 1
    if i < n - 1:
        moves += sum(abs(v) for v in carry.values())
if any(v != 0 for v in carry.values()):
    print(-1)
else:
    print(moves)
